(()=>{
'use strict';
const U='https://gfggmkeucgqkkyvummpu.supabase.co',K='sb_publishable_ptCVbq9h15prKhT0OO5Zmg_LkE3cbK0';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
const enc=s=>encodeURIComponent(String(s??''));
async function api(path,opts={}){const r=await fetch(U+path,{...opts,headers:{apikey:K,Authorization:`Bearer ${K}`,Accept:'application/json','Content-Type':'application/json',...(opts.headers||{})}});const t=await r.text();let d=[];try{d=t?JSON.parse(t):[]}catch{d=[]}if(!r.ok)throw new Error(d?.message||`HTTP ${r.status}`);return d}
function activate(id){document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));$(id)?.classList.add('active');document.querySelectorAll('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===id));window.scrollTo({top:0,behavior:'smooth'})}
function shell(title,kicker='PUBLIC',desc=''){return `<div class="public-page"><div class="public-head"><span class="eyebrow">${esc(kicker)}</span><h2>${esc(title)}</h2>${desc?`<p>${esc(desc)}</p>`:''}</div><div id="public-content"></div></div>`}
function cardProblem(x){return `<button class="public-list-card" data-problem="${esc(x.id)}"><span class="problem-icon">${x.category==='Infrastruktur'?'🛣️':x.category==='Kesehatan'?'🏥':x.category==='Pendidikan'?'🏫':'◉'}</span><span><b>${esc(x.title||'Masalah tanpa judul')}</b><small>${esc(x.category||'Masalah')} · ${esc(x.status||'tercatat')} ${x.updated_at?'· '+new Date(x.updated_at).toLocaleDateString('id-ID'):''}</small></span><em>Lihat detail →</em></button>`}
async function renderHome(){activate('home');const h=$('home');if(!h)return;document.querySelectorAll('.public-home-extra').forEach(x=>x.remove());}
async function renderMap(){activate('map');const h=$('map');h.innerHTML=shell('Peta Indonesia','PETA INDONESIA','Telusuri wilayah dari provinsi hingga desa, lalu buka masalah yang tercatat pada wilayah tersebut.');const c=$('public-content');c.innerHTML=`<div class="region-breadcrumb" id="regionCrumb"><button data-back>Indonesia</button></div><div class="region-layout"><div class="region-map-card"><div id="drillMap" class="drill-map"></div><div class="map-hint">Klik provinsi pada peta untuk mulai menelusuri wilayah.</div></div><div class="region-panel"><div id="regionPanel"><div class="public-loading">Memuat provinsi…</div></div></div></div>`;await loadTopRegions();setTimeout(initDrillMap,20)}
async function loadTopRegions(){try{const rows=await api('/rest/v1/regions?select=id,name,level,parent_region_id,source_name&source_name=eq.BIG&parent_region_id=is.null&order=name.asc&limit=100');renderRegionButtons(rows,'Provinsi');}catch(e){renderRegionError(e)}}
function renderRegionButtons(rows,label){const p=$('regionPanel');if(!p)return;p.innerHTML=`<div class="panel-title">${esc(label)} <span>${rows.length} wilayah</span></div><div class="region-grid">${rows.map(x=>`<button class="region-btn" data-region-id="${esc(x.id)}"><strong>${esc(x.name)}</strong><small>${esc(x.level||label)}</small></button>`).join('')}</div>`;p.querySelectorAll('[data-region-id]').forEach(b=>b.onclick=()=>openRegionById(b.dataset.regionId));}
function renderRegionError(e){$('regionPanel').innerHTML='<div class="public-empty">Data wilayah belum dapat dimuat. Silakan coba lagi.</div>'}
async function openRegionByName(name){try{const rows=await api(`/rest/v1/regions?select=id,name,level,parent_region_id&source_name=eq.BIG&name=ilike.*${enc(name)}*&limit=5`);if(rows[0])return openRegionById(rows[0].id);return null}catch{return null}}
async function openRegionById(id){try{const rows=await api(`/rest/v1/regions?select=id,name,level,parent_region_id&source_name=eq.BIG&id=eq.${enc(id)}&limit=1`);if(!rows[0])return;const r=rows[0];activate('map');const crumb=$('regionCrumb');const ancestors=await getAncestors(r);crumb.innerHTML=ancestors.map((a,i)=>`<button data-crumb="${esc(a.id)}">${esc(a.name)}</button>${i<ancestors.length-1?'<span>›</span>':''}`).join('')+'<span>›</span><b>'+esc(r.name)+'</b>';crumb.querySelectorAll('[data-crumb]').forEach(b=>b.onclick=()=>openRegionById(b.dataset.crumb));const panel=$('regionPanel');panel.innerHTML='<div class="public-loading">Memuat wilayah di dalam '+esc(r.name)+'…</div>';const children=await api(`/rest/v1/regions?select=id,name,level,parent_region_id&source_name=eq.BIG&parent_region_id=eq.${enc(r.id)}&order=name.asc&limit=200`);if(children.length){renderRegionButtons(children,displayLevel(children[0]?.level));return}await renderVillageProblems(r)}catch(e){renderRegionError(e)}}
function displayLevel(level){const s=String(level||'').toLowerCase();if(s.includes('prov'))return'Provinsi';if(s.includes('kab')||s.includes('kota')||s.includes('regenc'))return'Kabupaten/Kota';if(s.includes('kec'))return'Kecamatan';if(s.includes('desa')||s.includes('village')||s.includes('kelur'))return'Desa/Kelurahan';return'Wilayah berikutnya'}
async function getAncestors(r){const out=[];let cur=r;for(let i=0;i<6&&cur?.id;i++){out.unshift(cur);if(!cur.parent_region_id)break;const rows=await api(`/rest/v1/regions?select=id,name,level,parent_region_id&source_name=eq.BIG&id=eq.${enc(cur.parent_region_id)}&limit=1`);cur=rows[0]}return out}
async function renderVillageProblems(r){const p=$('regionPanel');try{const problems=await api(`/rest/v1/problems?select=id,title,category,status,updated_at,region_id&region_id=eq.${enc(r.id)}&order=updated_at.desc&limit=100`);p.innerHTML=`<div class="panel-title">Masalah di ${esc(r.name)} <span>${problems.length} tercatat</span></div>${problems.length?`<div class="problem-list">${problems.map(cardProblem).join('')}</div>`:'<div class="public-empty">Belum ada masalah publik yang tercatat langsung pada wilayah ini.</div>'}<button class="btn-primary region-report" data-report="${esc(r.name)}">Laporkan masalah di wilayah ini</button>`;p.querySelectorAll('[data-problem]').forEach(b=>b.onclick=()=>render('problem-detail',b.dataset.problem));p.querySelector('[data-report]')?.addEventListener('click',()=>render('report',r.name))}catch{p.innerHTML='<div class="public-empty">Masalah wilayah belum dapat dimuat.</div>'}}
function initDrillMap(){const el=$('drillMap');if(!el||!window.L||el._leaflet_id)return;const map=L.map(el,{zoomControl:true,attributionControl:false,scrollWheelZoom:false}).setView([-2.5,118],4.3);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:12,attribution:'© OpenStreetMap'}).addTo(map);fetch('https://raw.githubusercontent.com/superpikar/indonesia-geojson/master/indonesia-province-simple.json').then(r=>r.json()).then(data=>{const layer=L.geoJSON(data,{style:{color:'#fff',weight:1,fillColor:'#1e88e5',fillOpacity:.75},onEachFeature:(f,l)=>{const p=f.properties||{},name=p.name||p.NAME_1||p.Propinsi||p.province||'Provinsi';l.bindTooltip(name,{sticky:true});l.on('mouseover',e=>e.target.setStyle({weight:2,fillOpacity:.95}));l.on('mouseout',e=>layer.resetStyle(e.target));l.on('click',()=>openRegionByName(name))}}).addTo(map);map.fitBounds(layer.getBounds(),{padding:[10,10]})}).catch(()=>{})}
async function renderProblems(){activate('problems');const h=$('problems');h.innerHTML=shell('Masalah Publik','MASALAH','Daftar masalah yang tercatat secara publik. Buka detail untuk melihat wilayah, status, dan konteks.');const c=$('public-content');c.innerHTML='<div class="public-loading">Memuat masalah…</div>';try{const rows=await api('/rest/v1/problems?select=id,title,category,status,updated_at,region_id&order=updated_at.desc&limit=100');c.innerHTML=rows.length?`<div class="problem-list full-list">${rows.map(cardProblem).join('')}</div>`:'<div class="public-empty">Belum ada masalah publik yang tersedia.</div>';c.querySelectorAll('[data-problem]').forEach(b=>b.onclick=()=>render('problem-detail',b.dataset.problem))}catch{c.innerHTML='<div class="public-empty">Data masalah belum dapat dimuat.</div>'}}
async function renderProblemDetail(id){activate('problems');const h=$('problems');h.innerHTML=shell('Detail Masalah','MASALAH');const c=$('public-content');c.innerHTML='<div class="public-loading">Memuat detail…</div>';try{const rows=await api(`/rest/v1/problems?select=id,title,category,status,description,region_id,created_at,updated_at&id=eq.${enc(id)}&limit=1`);const x=rows[0];if(!x){c.innerHTML='<div class="public-empty">Masalah tidak ditemukan.</div>';return}let region=null;try{region=(await api(`/rest/v1/regions?select=id,name,level,parent_region_id&source_name=eq.BIG&id=eq.${enc(x.region_id)}&limit=1`))[0]}catch{}c.innerHTML=`<article class="problem-detail-card"><button class="back-link" id="backProblems">← Kembali ke masalah</button><span class="eyebrow">${esc(x.category||'MASALAH')}</span><h2>${esc(x.title)}</h2><div class="detail-meta"><span>Status: ${esc(x.status||'tercatat')}</span><span>Wilayah: ${esc(region?.name||'Belum ditentukan')}</span><span>Terakhir diperbarui: ${x.updated_at?new Date(x.updated_at).toLocaleDateString('id-ID'):'-'}</span></div><div class="detail-body">${esc(x.description||'Belum ada uraian publik untuk masalah ini.')}</div><div class="detail-actions"><button class="btn-primary" data-report="${esc(region?.name||'')}">Laporkan informasi terkait</button>${region?'<button class="btn-outline" data-region="'+esc(region.id)+'">Lihat wilayah</button>':''}</div></article>`;c.querySelector('#backProblems').onclick=()=>render('problems');c.querySelector('[data-report]')?.addEventListener('click',e=>render('report',e.currentTarget.dataset.report));c.querySelector('[data-region]')?.addEventListener('click',e=>openRegionById(e.currentTarget.dataset.region))}catch{c.innerHTML='<div class="public-empty">Detail masalah belum dapat dimuat.</div>'}}
async function renderData(){activate('data');const h=$('data');h.innerHTML=shell('Data & Statistik','DATA PUBLIK','Ringkasan statistik dari data yang tersedia untuk publik.');const c=$('public-content');c.innerHTML='<div class="public-loading">Menghitung ringkasan…</div>';try{const rows=await api('/rest/v1/problems?select=id,status,category&limit=1000');const counts={};rows.forEach(x=>counts[x.category||'Lainnya']=(counts[x.category||'Lainnya']||0)+1);c.innerHTML=`<div class="stats-grid"><div class="stat-card"><b>${rows.length}</b><span>Masalah publik</span></div><div class="stat-card"><b>${new Set(rows.map(x=>x.category).filter(Boolean)).size}</b><span>Kategori</span></div><div class="stat-card"><b>${rows.filter(x=>String(x.status||'').toLowerCase().includes('selesai')).length}</b><span>Status selesai* </span></div></div><div class="category-stats">${Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<button data-cat="${esc(k)}"><b>${esc(k)}</b><span>${v} masalah</span></button>`).join('')}</div><small>* Mengikuti nilai status yang tersimpan pada data publik.</small>`;c.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>render('problems'))}catch{c.innerHTML='<div class="public-empty">Statistik belum dapat dimuat.</div>'}}
function renderMonitoring(){activate('monitoring');const h=$('monitoring');h.innerHTML=shell('Pantau Perubahan','PEMANTAUAN','Ikuti perubahan status masalah melalui pembaruan data publik.');$('public-content').innerHTML='<div class="info-grid"><div class="info-card"><b>Status</b><p>Setiap masalah dapat memiliki status yang berubah setelah pembaruan data.</p></div><div class="info-card"><b>Waktu</b><p>Detail masalah menampilkan waktu pembaruan terakhir bila tersedia.</p></div><div class="info-card"><b>Telusur</b><p>Gunakan Peta Indonesia untuk melihat masalah berdasarkan wilayah.</p></div></div>'}
function renderSolutions(){activate('solutions');const h=$('solutions');h.innerHTML=shell('Solusi','RUANG PUBLIK','Ruang untuk memahami konteks masalah dan mengarahkan tindak lanjut berbasis informasi.');$('public-content').innerHTML='<div class="info-grid"><div class="info-card"><b>Pahami masalah</b><p>Mulai dari wilayah, masalah, status, dan sumber informasi yang tersedia.</p></div><div class="info-card"><b>Tambahkan laporan</b><p>Warga dapat mengirim informasi baru. Laporan dipisahkan dari fakta terverifikasi.</p></div><div class="info-card"><b>Ikuti perubahan</b><p>Pantau pembaruan pada masalah yang sudah tercatat.</p></div></div>'}
function renderAccount(){activate('account');const h=$('account');h.innerHTML=shell('Akun','AKSES PUBLIK','Fitur akun publik dapat ditambahkan tanpa membuka kontrol internal sistem.');$('public-content').innerHTML='<div class="info-card"><b>Masuk / Daftar</b><p>Area akun publik sedang disiapkan. Tidak ada kontrol internal atau kredensial admin yang ditampilkan di sini.</p></div>'}
function renderMore(){activate('more');const h=$('more');h.innerHTML=shell('Tentang WASKITA','TENTANG','WASKITA — Indonesia Punya Masalah. Lihat. Pahami. Antisipasi.');$('public-content').innerHTML='<div class="info-card"><b>Ruang publik</b><p>WASKITA menyajikan masalah, wilayah, data publik, laporan warga, dan perubahan secara terpisah dari mesin internal.</p></div>'}
async function renderSearch(q){activate('result');const h=$('result');h.innerHTML=shell('Hasil Pencarian','PENCARIAN',`Hasil untuk “${q}”`);const c=$('public-content');try{const [problems,regions]=await Promise.all([api(`/rest/v1/problems?select=id,title,category,status,region_id&title=ilike.*${enc(q)}*&limit=30`),api(`/rest/v1/regions?select=id,name,level,parent_region_id&source_name=eq.BIG&name=ilike.*${enc(q)}*&limit=30`)]);c.innerHTML=`<div class="search-results"><div><h3>Wilayah (${regions.length})</h3>${regions.map(r=>`<button class="public-list-card" data-region-id="${esc(r.id)}"><span class="problem-icon">📍</span><span><b>${esc(r.name)}</b><small>${esc(r.level||'Wilayah')}</small></span><em>Buka →</em></button>`).join('')||'<div class="public-empty">Tidak ada wilayah.</div>'}</div><div><h3>Masalah (${problems.length})</h3>${problems.map(cardProblem).join('')||'<div class="public-empty">Tidak ada masalah.</div>'}</div></div>`;c.querySelectorAll('[data-region-id]').forEach(b=>b.onclick=()=>openRegionById(b.dataset.regionId));c.querySelectorAll('[data-problem]').forEach(b=>b.onclick=()=>render('problem-detail',b.dataset.problem))}catch{c.innerHTML='<div class="public-empty">Pencarian belum dapat diproses.</div>'}}
function renderReport(prefill=''){activate('report');const h=$('report');h.innerHTML=`<div class="public-page"><div class="public-head"><span class="eyebrow">SUARA WARGA</span><h2>Ceritakan Masalah di Sekitar Anda</h2><p>Laporan warga menjadi sinyal awal dan tidak otomatis dianggap sebagai fakta. Laporan tetap melalui verifikasi.</p></div><div class="info-card report-form"><label>Judul masalah<input id="pr-title" value="${esc(prefill)}" placeholder="Contoh: Jalan rusak di Dusun…"></label><label>Kategori<select id="pr-cat"><option>Infrastruktur</option><option>Ekonomi</option><option>Pendidikan</option><option>Kesehatan</option><option>Lingkungan</option><option>Sosial</option><option>Lainnya</option></select></label><label>Wilayah<input id="pr-region" placeholder="Desa / Kecamatan / Kabupaten / Provinsi"></label><label>Waktu kejadian<input id="pr-time" type="datetime-local"></label><label class="full">Deskripsi / kronologi<textarea id="pr-body" rows="7" placeholder="Apa yang terjadi, sejak kapan, siapa yang terdampak, dan informasi apa yang tersedia?"></textarea></label><div class="form-note">Narasi warga dipisahkan dari evidence. Verifikasi diperlukan.</div><button id="pr-submit" class="btn-primary">Kirim Laporan</button><div id="pr-status" class="notice" style="display:none"></div></div></div>`;$('pr-submit').onclick=submitReport}
async function submitReport(){const st=$('pr-status'),title=$('pr-title').value.trim(),body=$('pr-body').value.trim(),rn=$('pr-region').value.trim(),category=$('pr-cat').value;st.style.display='block';if(!title||!body){st.textContent='Judul dan deskripsi wajib diisi.';return}st.textContent='Mengirim laporan…';let region_id=null;try{if(rn){const r=await api(`/rest/v1/regions?select=id&source_name=eq.BIG&name=ilike.*${enc(rn)}*&limit=1`);region_id=r[0]?.id||null}}catch{}const payload={title,narrative:body,category,region_id,occurred_at:$('pr-time').value?new Date($('pr-time').value).toISOString():new Date().toISOString(),verification_status:'received',classification:'citizen_report'};try{await api('/rest/v1/human_reports',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(payload)});st.className='notice success';st.textContent='Laporan diterima dan menunggu verifikasi.'}catch{st.className='notice';st.textContent='Server belum menerima penulisan langsung. Laporan disimpan sementara di perangkat ini.';const old=JSON.parse(localStorage.getItem('ipm_reports')||'[]');old.unshift({...payload,id:crypto.randomUUID(),region_name:rn,created_at:new Date().toISOString(),sync:'local'});localStorage.setItem('ipm_reports',JSON.stringify(old.slice(0,100)))}}
function installStyles(){const s=document.createElement('style');s.textContent=`.public-page{max-width:1180px;margin:0 auto;padding:34px 24px 60px}.public-head{margin-bottom:22px}.public-head h2{margin:5px 0 7px;font-size:30px}.public-head p{color:#66788d;max-width:780px}.region-breadcrumb{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:14px;color:#66788d}.region-breadcrumb button{border:0;background:none;color:#1769aa;font-weight:800;cursor:pointer}.region-layout{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(360px,.8fr);gap:18px}.region-map-card{border:1px solid #dce6ef;border-radius:16px;overflow:hidden;background:#f5f8fb}.drill-map{height:620px}.map-hint{padding:11px 14px;font-size:11px;color:#66788d;background:#fff}.region-panel{min-height:620px;border:1px solid #dce6ef;border-radius:16px;background:#fff;padding:18px}.panel-title{font-size:15px;font-weight:800;margin-bottom:13px}.panel-title span{float:right;color:#7a8b9e;font-size:10px;font-weight:600}.region-grid{display:grid;grid-template-columns:1fr;gap:8px;max-height:560px;overflow:auto}.region-btn{display:flex;justify-content:space-between;align-items:center;text-align:left;border:1px solid #e1e8ef;background:#f9fbfd;border-radius:11px;padding:12px;cursor:pointer}.region-btn:hover{border-color:#2b8bc6;background:#f2f8fd}.region-btn strong{font-size:12px}.region-btn small{color:#8090a2;font-size:9px}.public-list-card{width:100%;display:grid;grid-template-columns:38px 1fr auto;gap:10px;align-items:center;text-align:left;border:1px solid #e1e8ef;background:#fff;border-radius:12px;padding:12px;margin-bottom:9px;cursor:pointer}.public-list-card:hover{border-color:#2b8bc6}.problem-icon{width:32px;height:32px;border-radius:9px;background:#eef6fb;display:grid;place-items:center}.public-list-card b{display:block;font-size:12px}.public-list-card small{display:block;color:#7b8b9d;font-size:9px;margin-top:3px}.public-list-card em{font-size:9px;color:#2674aa;font-style:normal;font-weight:800}.problem-list.full-list{max-width:900px}.public-empty,.public-loading{padding:28px;text-align:center;color:#77899b;background:#f7fafc;border:1px dashed #d6e1eb;border-radius:12px}.problem-detail-card{max-width:900px;border:1px solid #dce6ef;border-radius:16px;padding:24px;background:#fff}.problem-detail-card h2{font-size:28px;margin:8px 0}.back-link{border:0;background:none;color:#2674aa;font-weight:800;cursor:pointer;margin-bottom:20px}.detail-meta{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.detail-meta span{font-size:10px;background:#f3f7fa;border-radius:999px;padding:7px 10px;color:#65778a}.detail-body{padding:18px 0;border-top:1px solid #e8eef3;border-bottom:1px solid #e8eef3;line-height:1.7;color:#4e6175;white-space:pre-wrap}.detail-actions{display:flex;gap:9px;margin-top:16px}.stats-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.stat-card,.info-card{border:1px solid #dce6ef;border-radius:14px;background:#fff;padding:20px}.stat-card b{font-size:28px;display:block}.stat-card span{font-size:11px;color:#74869a}.category-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.category-stats button{border:1px solid #dce6ef;background:#fff;border-radius:12px;padding:14px;text-align:left;cursor:pointer}.category-stats b,.category-stats span{display:block}.category-stats span{font-size:10px;color:#788a9d;margin-top:5px}.info-grid,.search-results{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.search-results{grid-template-columns:1fr 1fr}.info-card b{font-size:14px}.info-card p{font-size:12px;line-height:1.65;color:#687a8e}.report-form{max-width:850px;display:grid;grid-template-columns:1fr 1fr;gap:13px}.report-form label{font-size:10px;font-weight:800;color:#5f7184}.report-form input,.report-form select,.report-form textarea{display:block;width:100%;box-sizing:border-box;margin-top:6px;border:1px solid #dce6ef;border-radius:9px;padding:11px;background:#fff;font:inherit}.report-form .full,.report-form .form-note,.report-form button,.report-form .notice{grid-column:1/-1}.form-note{padding:10px;background:#f5f9fc;color:#718297;font-size:10px;border-radius:9px}.notice{padding:11px;background:#f4f8fb;border-radius:9px;font-size:11px}.notice.success{background:#eefaf4;color:#20734b}.region-report{margin-top:14px}@media(max-width:900px){.region-layout,.search-results,.info-grid{grid-template-columns:1fr}.drill-map{height:440px}.region-panel{min-height:auto}.stats-grid,.category-stats{grid-template-columns:1fr}.report-form{grid-template-columns:1fr}.report-form .full,.report-form .form-note,.report-form button,.report-form .notice{grid-column:auto}}`;document.head.appendChild(s)}
window.openPublicRegion=openRegionByName;window.renderPublicRegion=openRegionByName;window.render=async function(v,x=''){if(v==='home')return renderHome();if(v==='map'||v==='regions')return renderMap();if(v==='problems')return renderProblems();if(v==='problem-detail')return renderProblemDetail(x);if(v==='data')return renderData();if(v==='report')return renderReport(x);if(v==='monitoring')return renderMonitoring();if(v==='solutions')return renderSolutions();if(v==='account')return renderAccount();if(v==='more')return renderMore();if(v==='result')return renderSearch(x)};
document.addEventListener('DOMContentLoaded',()=>{installStyles();document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>render(b.dataset.view)));const q=$('question'),ask=$('ask'),hs=$('headerSearch');const search=()=>{const v=q?.value.trim();if(v)render('result',v)};ask?.addEventListener('click',search);q?.addEventListener('keydown',e=>{if(e.key==='Enter')search()});hs?.addEventListener('click',()=>q?.focus());render('home')});
})();
